// static
bool StructTraits<::crosapi::mojom::Volume::DataView, ::crosapi::mojom::VolumePtr>::Read(
    ::crosapi::mojom::Volume::DataView input,
    ::crosapi::mojom::VolumePtr* output) {
  bool success = true;
  ::crosapi::mojom::VolumePtr result(::crosapi::mojom::Volume::New());
  
      if (success && !input.ReadVolumeId(&result->volume_id))
        success = false;
      if (success && !input.ReadVolumeLabel(&result->volume_label))
        success = false;
      if (success)
        result->writable = input.writable();
      if (success && !input.ReadMountPath(&result->mount_path))
        success = false;
      if (success)
        result->is_available_to_lacros = input.is_available_to_lacros();
  *output = std::move(result);
  return success;
}

